package com.minimarket.inventario.service; import com.minimarket.common.exception.*; import com.minimarket.inventario.dto.*; import com.minimarket.inventario.entity.*; import com.minimarket.inventario.repository.*; import com.minimarket.producto.repository.ProductoRepository; import com.minimarket.security.CurrentUserService; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; @Service @RequiredArgsConstructor public class InventarioServiceImpl implements InventarioService{private final InventarioMovimientoRepository mov;private final ProductoRepository productos;private final LoteRepository lotes;private final CurrentUserService current;
 @Override @Transactional public InventarioResponseDTO registrar(MovimientoInventarioRequest r){var p=productos.findById(r.productoId()).orElseThrow(()->ResourceNotFoundException.of("Producto",r.productoId()));if(!Boolean.TRUE.equals(p.getControlaStock()))throw new BusinessException("El producto no controla stock");var old=p.getStockActual();boolean positivo=suma(r.tipo());BigDecimal nuevo=positivo?old.add(r.cantidad()):old.subtract(r.cantidad());if(nuevo.signum()<0)throw new BusinessException("Stock insuficiente");Lote lote=null;if(r.loteId()!=null)lote=lotes.findById(r.loteId()).orElseThrow(()->ResourceNotFoundException.of("Lote",r.loteId()));p.setStockActual(nuevo);var m=InventarioMovimiento.builder().producto(p).lote(lote).tipoMovimiento(r.tipo()).cantidad(r.cantidad()).stockAnterior(old).stockResultante(nuevo).motivo(r.motivo()).referenciaTipo(r.referenciaTipo()).referenciaId(r.referenciaId()).usuario(current.getUsuario()).build();return d(mov.save(m));}
 private boolean suma(InventarioMovimiento.TipoMovimientoInventario t){return t==InventarioMovimiento.TipoMovimientoInventario.ENTRADA||t==InventarioMovimiento.TipoMovimientoInventario.AJUSTE_POSITIVO||t==InventarioMovimiento.TipoMovimientoInventario.DEVOLUCION_VENTA;}
 @Override @Transactional(readOnly=true) public Page<InventarioResponseDTO> kardex(Long id,Pageable p){return mov.findByProductoIdOrderByCreatedAtDesc(id,p).map(this::d);}
 private InventarioResponseDTO d(InventarioMovimiento m){return new InventarioResponseDTO(m.getId(),m.getProducto().getId(),m.getProducto().getNombre(),m.getLote()!=null?m.getLote().getId():null,m.getTipoMovimiento().name(),m.getCantidad(),m.getStockAnterior(),m.getStockResultante(),m.getMotivo(),m.getUsuario().getId(),m.getCreatedAt());}}
